import React, { useState } from 'react';
import { NavLink } from 'react-router-dom';

import styles from '../../css/Searchprod.module.css'
import prod from '../../css/Tradings.module.css'

import { useGetProductsQuery } from '../../features/api/apiSlice';
import Prods from '../Prods/Prods';

const SingleCategory = () => {
  const [values, setValues] = useState({
    title: "",
    price: 0,
  })

  const DOTS = [1, 2, 3, 4]
  const [isActiveDot, setSize] = useState(0);

  const handleChange = ({ target: { value, name } }) => {
    setValues({ ...values, [name]: value })
  }

  const { data, isLoading } = useGetProductsQuery({ ...values });
  const list = data?.filter((_, i) => i < 8)

  return (
    <div className='container'>
      <div className={styles.searchprod}>
        <div className={styles["searchprod-title"]}>Sneakers</div>
        <div className={styles.search_field}>
          <input
            type="text"
            className={styles.search_input + ' ' + styles.prodname}
            value={values.title}
            onChange={handleChange}
            placeholder='Product name' />
          <input
            type="text"
            className={styles.search_input + ' ' + styles.priceprod}
            value={values.price}
            onChange={handleChange}
            placeholder='Price from' />
        </div>
        <ul className={prod.prodbox}>
          {list && list.map((el) => (
            <li className={prod.prodbox_item} key={el.id}><NavLink to={`/product/${el.id}`}><Prods prod={el} /></NavLink></li>
          ))}
        </ul>
        <div className={styles['dots-box']}>
          {DOTS.map(({ size }, index) => (
            <li onClick={() => setSize(index)} className={(isSize == index ? styles['size-value-item--active'] : '') + ' ' + styles['size-value-item']}>{SIZE[index]}</li>
          ))}
          <button className={styles['dots-item']}>1</button>
          <button className={styles['dots-item']}>2</button>
          <button className={styles['dots-item']}>3</button>
          <button className={styles['dots-item']}>4</button>
        </div>
      </div>
    </div>
  );
}

export default SingleCategory;
